SID = {};

SID._channels = 1;
SID._sampleRate= 44100;



SID.getAudioBuffer = function() {
  var ptr = backend_SID.Module.ccall('getSoundBuffer', 'number');      
  return ptr>>1;  // 16 bit samples      
}


SID.getChannelBuffer = function(channel) {
  var ptr = 0;
  switch(channel) {
    case 1:
      ptr = backend_SID.Module.ccall('getSoundBuffer1', 'number');      
      break;
    case 2:
      ptr = backend_SID.Module.ccall('getSoundBuffer2', 'number');      
      break;
    case 3:
      ptr = backend_SID.Module.ccall('getSoundBuffer3', 'number');      
      break;
    case 4:
      ptr = backend_SID.Module.ccall('getSoundBufferDigi', 'number');      
      break;
  }
  return ptr>>1;  // 16 bit samples      
}

SID.getAudioBufferLength =  function() {
  var len= backend_SID.Module.ccall('getSoundBufferLen', 'number');
  return len;
}

SID.computeAudioSamples = function() {
  var len= backend_SID.Module.ccall('computeAudioSamples', 'number');
  if (len <= 0) return 1; // >0 means "end song"
  
  return 0; 
}
SID.getPathAndFilename= function(filename) {
  return ['/', filename];
}
SID.registerFileData= function(pathFilenameArray, data) {
  return 0; // FS not used in Tiny'R'Sid
}

SID.allocResampleBuffer = function(s) {
  return new Float32Array(s);
}

SID._resampleBuffer = new Float32Array(1);

SID.resetSampleRate = function(sampleRate, inputSampleRate) {
  if (sampleRate > 0) { this._sampleRate= sampleRate; }
  if (inputSampleRate > 0) { this._inputSampleRate= inputSampleRate; }
    
  var s= Math.round(SAMPLES_PER_BUFFER *this._sampleRate/this._inputSampleRate);
  
  if (s > this._resampleBuffer.length) {
    this._resampleBuffer= this.allocResampleBuffer(s);
  }
}

SID.getResampleBuffer = function() {
  return this._resampleBuffer;
}



SID.loadMusicData = function(sampleRate, path, filename, data) {
  var buf = backend_SID.Module._malloc(data.length);
  backend_SID.Module.HEAPU8.set(data, buf);
  var ret = backend_SID.Module.ccall('loadSidFile', 'number', ['number', 'number'], [buf, data.length]);
  backend_SID.Module._free(buf);

  console.log('ret = ' + ret);
  if (ret == 0) {
    console.log('sample rate = ' + sampleRate);
    this.playerSampleRate = backend_SID.Module.ccall('getSampleRate', 'number');
    this.resetSampleRate(sampleRate, this.playerSampleRate); 
  }
  return ret;     
}

SID.evalTrackOptions = function(options) {     
  return backend_SID.Module.ccall('playTune', 'number', ['number'], [options.track]);
}        

SID.updateSongInfo = function(filename, result) {
  var ret = backend_SID.Module.ccall('getMusicInfo', 'number');
        
  var array = backend_SID.Module.HEAP32.subarray(ret>>2, (ret>>2)+7);
  result.loadAddr= backend_SID.Module.HEAP32[((array[0])>>2)]; // i32
  result.playSpeed= backend_SID.Module.HEAP32[((array[1])>>2)]; // i32
  result.maxSubsong= backend_SID.Module.HEAP8[(array[2])]; // i8
  result.actualSubsong= backend_SID.Module.HEAP8[(array[3])]; // i8
  result.songName= backend_SID.Module.Pointer_stringify(array[4]);
  result.songAuthor= backend_SID.Module.Pointer_stringify(array[5]);
  result.songReleased= backend_SID.Module.Pointer_stringify(array[6]);     
}

SID.getCopiedAudio = function(buffer, len) {
  var i;
  // just copy the rescaled values so there is no need for special handling in playback loop
  for(i= 0; i<len*this._channels; i++){
    this._resampleBuffer[i]= this.readFloatSample(buffer, i); 
  }   
  return len; 
}


SID.getResampledAudio = function(buffer, len) {  
  var resampleLen;
  if (this._sampleRate == this._inputSampleRate) {    
    resampleLen= this.getCopiedAudio(buffer, len);
  } else {
    resampleLen= Math.round(len * this._sampleRate / this._inputSampleRate);  
    var bufSize= resampleLen * this._channels;  // for each of the x channels
    
    if (bufSize > this._resampleBuffer.length) { this._resampleBuffer= this.allocResampleBuffer(bufSize); }
    
    // only mono and interleaved stereo data is currently implemented..
    this.resampleChannel(0, buffer, len, resampleLen);
    if (this._channels == 2) {
      this.resampleChannel(1, buffer, len, resampleLen);
    }
  }
  return resampleLen;
}
SID.resampleChannel =  function(channelId, buffer, len, resampleLen) {
  // Bresenham algorithm based resampling
  var x0= 0;
  var y0= 0;
  var x1= resampleLen - 0;
  var y1= len - 0;

  var dx =  Math.abs(x1-x0), sx = x0<x1 ? 1 : -1;
  var dy = -Math.abs(y1-y0), sy = y0<y1 ? 1 : -1;
  var err = dx+dy, e2;

  var i;
  for(;;){
    i= (x0*this._channels) + channelId;
    this._resampleBuffer[i]= this.readFloatSample(buffer, (y0*this._channels) + channelId);

    if (x0>=x1 && y0>=y1) { break; }
    e2 = 2*err;
    if (e2 > dy) { err += dy; x0 += sx; }
    if (e2 < dx) { err += dx; y0 += sy; }
  }
}

SID.readFloatSample =  function(buffer, idx) {
  return (backend_SID.Module.HEAP16[buffer+idx])/0x8000;
}

SID.enableVoices = function(mask) {
  backend_SID.Module.ccall('enableVoices', 'number', ['number'], [mask]);  
}

SID.setFilterEnabled = function(enable) {
  if(enable) {
    enable = 1;
  } else {
    enable = 0;
  }
  backend_SID.Module.ccall('setFilterEnabled', 'number', ['number'], [enable]);  
  
}


SID.getEnvelope = function(voice) {
  return backend_SID.Module.ccall('getEnvelope', 'number', ['number'], [voice]);
}

SID.getWave = function(voice) {
  return backend_SID.Module.ccall('getWave', 'number', ['number'], [voice]);
}


SID.getFrequency = function(voice) {
  return backend_SID.Module.ccall('getFrequency', 'number', ['number'], [voice]);
}

SID.getAD = function(voice) {
  return backend_SID.Module.ccall('getAD', 'number', ['number'], [voice]);
}

SID.getSR = function(voice) {
  return backend_SID.Module.ccall('getSR', 'number', ['number'], [voice]);
}

  